    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 depositsCountBefore;
        try c.depositsCount() returns (uint256 __r) { depositsCountBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
